primaryQuery:
run: inventory_items -> {
  extend: { join_one: oi is order_items on id = oi.inventory_item_id }
  where: sold_at is null or oi.status = 'Cancelled'
  aggregate:
    unsold_units is count()
    unsold_at_cost is round(cost.sum(), 2)
}

verifyQuery:
run: inventory_items extend {
  join_one: oi is order_items on id = oi.inventory_item_id
} -> {
  aggregate:
    all_units is count()
    sold_units is count() { where: sold_at is not null and coalesce(oi.status, '') != 'Cancelled' }
    all_cost is cost.sum()
    sold_cost is cost.sum() { where: sold_at is not null and coalesce(oi.status, '') != 'Cancelled' }
} -> {
  select:
    unsold_units is all_units - sold_units
    unsold_at_cost is round(all_cost - sold_cost, 2)
}
